db, err := sql.Open("pgx", dsn) // lazy: builds the pool, does NOT connect
if err != nil {
	log.Fatal(err)
}
defer db.Close()

// Force a real connection to fail fast if the DB is unreachable.
ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
defer cancel()
if err := db.PingContext(ctx); err != nil {
	log.Fatalf("unreachable: %v", err)
}
// One *sql.DB shared by every goroutine for the life of the process.

// Cap the pool against the DB's connection budget across all instances.
db.SetMaxOpenConns(25) // hard cap: in-use + idle connections
db.SetMaxIdleConns(25) // match the max to avoid open/close churn

// Inspect live pool state to confirm sizing under load.
s := db.Stats()
log.Printf("open=%d inUse=%d idle=%d waitCount=%d",
	s.OpenConnections, s.InUse, s.Idle, s.WaitCount)
// Rising WaitCount means callers are blocking on an undersized pool.

// Background timers prune connections so the pool stays healthy.
db.SetConnMaxLifetime(30 * time.Minute) // recycle so LBs can rebalance
db.SetConnMaxIdleTime(5 * time.Minute)  // release idle conns in quiet periods

// Stats reveal how many connections the timers have retired.
s := db.Stats()
log.Printf("closedByLifetime=%d closedByIdle=%d",
	s.MaxLifetimeClosed, s.MaxIdleTimeClosed)
// A steady closedByLifetime count is normal recycling, not a leak.

rows, err := db.QueryContext(ctx, "SELECT name FROM users")
if err != nil {
	return nil, err
}
defer rows.Close() // ALWAYS returns the connection, even on early return

var names []string
for rows.Next() {
	var n string
	if err := rows.Scan(&n); err != nil {
		return nil, err // safe: deferred Close still runs
	}
	names = append(names, n)
}
if err := rows.Err(); err != nil { // Next()==false can mean error, not just EOF
	return nil, err
}
return names, nil

// The context deadline bounds the query and frees the connection on timeout.
ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
defer cancel()

var count int
err := db.QueryRowContext(ctx,
	"SELECT count(*) FROM jobs WHERE done = false").Scan(&count)
if errors.Is(err, context.DeadlineExceeded) {
	return fmt.Errorf("query timed out: %w", err) // driver cancels; conn returned
}
if err != nil {
	return err
}
// Cancellation propagates to the driver, so a pinned connection is released.

// Compile once, reuse for many lookups with different arguments.
stmt, err := db.PrepareContext(ctx, "SELECT name FROM users WHERE id = $1")
if err != nil {
	return err
}
defer stmt.Close() // release the prepared statement's pooled resources

for _, id := range ids {
	var name string
	// Parameter binding prevents SQL injection; the plan is not re-parsed.
	if err := stmt.QueryRowContext(ctx, id).Scan(&name); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			continue
		}
		return err
	}
	log.Printf("user %d = %s", id, name)
}

tx, err := db.BeginTx(ctx, nil) // checks out ONE connection for the whole tx
if err != nil {
	return err
}
defer tx.Rollback() // no-op after Commit; safety net that returns the conn

if _, err := tx.ExecContext(ctx,
	"UPDATE accounts SET balance = balance - $1 WHERE id = $2", amt, from); err != nil {
	return err // deferred Rollback frees the pinned connection
}
if _, err := tx.ExecContext(ctx,
	"UPDATE accounts SET balance = balance + $1 WHERE id = $2", amt, to); err != nil {
	return err
}
return tx.Commit() // both updates commit atomically; connection returns to pool

