package main

import (
	"context"
	"database/sql"
	"log"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" driver
)

func openDB(dsn string) (*sql.DB, error) {
	db, err := sql.Open("pgx", dsn) // builds the pool; does NOT connect
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(25)              // hard cap: in-use + idle
	db.SetMaxIdleConns(25)              // match max to avoid churn
	db.SetConnMaxLifetime(30 * time.Minute) // recycle so LBs can rebalance
	db.SetConnMaxIdleTime(5 * time.Minute)  // release during quiet periods

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := db.PingContext(ctx); err != nil { // fail fast if DB is down
		db.Close()
		return nil, err
	}
	return db, nil
}

func main() {
	db, err := openDB("postgres://user:pass@localhost:5432/app")
	if err != nil {
		log.Fatalf("db init: %v", err)
	}
	defer db.Close()
	log.Println("pool ready")
}

