package solution

import (
	"context"
	"database/sql"
)

// WithTx runs fn inside a transaction, committing on success and rolling back
// on any error or panic, so callers never manage Commit/Rollback themselves.
func WithTx(ctx context.Context, db *sql.DB, fn func(*sql.Tx) error) (err error) {
	tx, err := db.BeginTx(ctx, nil) // checks out one connection for the tx
	if err != nil {
		return err
	}
	// Guarantee the connection is freed even if fn panics.
	defer func() {
		if p := recover(); p != nil {
			_ = tx.Rollback() // release the pinned connection
			panic(p)          // re-panic so the caller still sees it
		}
	}()

	if err = fn(tx); err != nil {
		_ = tx.Rollback() // fn failed: undo and free the connection
		return err
	}
	return tx.Commit() // success: commit atomically and return the connection
}
